```json
{
  "root_causes": [
    {
      "service": "recommendation",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, service_name, attr_k8s_deployment_name, count(*) n, min(time) mn, max(time) mx, avg(value) avg_v FROM abnormal_metrics WHERE metric IN ('k8s.deployment.available','k8s.deployment.desired') AND service_name='recommendation' GROUP BY ALL",
          "claim": "In the abnormal window recommendation has k8s.deployment.available = 0 for all samples while desired stays 1."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'normal' p, service_name, span_name, attr_span_kind, count(*) n FROM normal_traces WHERE span_name LIKE 'recommendation.%' GROUP BY ALL UNION ALL SELECT 'abnormal', service_name, span_name, attr_span_kind, count(*) FROM abnormal_traces WHERE span_name LIKE 'recommendation.%' GROUP BY ALL",
          "claim": "Recommendation server spans fall from 882 in the normal period to 1 in the abnormal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /recommendations','recommendation.Recommendation/GetRecommendations') GROUP BY ALL",
          "claim": "Frontend /recommendations returns HTTP 500 on 857 requests, each failing on its GetRecommendations client call to recommendation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "recommendation",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND attr_status_code='Error' GROUP BY ALL",
          "claim": "Frontend's error spans are only the HTTP /recommendations server spans and their failed GetRecommendations client calls."
        }
      ]
    }
  ]
}
```

